/**
 * ─────────────────────────────────────────────────────────────────────────────
 * Channel lifecycle
 *
 * CH-01: the channel identifier is "jbc1" + base32(signing_key). channel_name is a
 * mutable label and MUST NOT be used as an identifier anywhere (CH-06).
 * ─────────────────────────────────────────────────────────────────────────────
 */
export interface ChannelDeclare {
  /** Human label — NOT an identifier. */
  channel_name: string;
  description: string;
  kind: ChannelKind;
  categories: BroadcastCategory[];
  default_area?: GeoArea | undefined;
  claims: IdentityClaim[];
  /** Ed25519 — this is the channel identity. */
  signing_key: Uint8Array;
  /** ML-KEM-768, for encrypted broadcasts. */
  kem_public_key: Uint8Array;
  /** ML-DSA-44 attestation key. */
  pq_key: Uint8Array;
  /** BCP-47, e.g. "bn" | "en". */
  language: string;
  valid_from: bigint;
}

export interface ChannelUpdate {
  channel: string;
  patch?: ChannelDeclare | undefined;
}

export interface ChannelRetire {
  channel: string;
  note: string;
  successor_key: Uint8Array;
}

/**
 * CH-03: signed by the OLD key. This is what preserves subscriber lists across a key
 * change — subscribers follow a channel, and continuity is established cryptographically.
 */
export interface ChannelRotate {
  channel: string;
  new_signing_key: Uint8Array;
  new_kem_key: Uint8Array;
  effective_from_ms: bigint;
}

/**
 * A key alone means nothing. There is no certificate authority here; there is
 * accumulated evidence, and the client shows its weight (Plans/01 §5).
 */
export interface IdentityClaim {
  kind: ClaimKind;
  value: string;
  /** Where and how it can be checked. */
  proof: string;
  asserted_at_ms: bigint;
}

/**
 * CV-02: no single authority may confer verification. Instance attestation is one
 * signal among several and MUST be overridable by the user.
 */
export interface ChannelVouch {
  channel: string;
  level: VouchLevel;
  /** "verified in person", "known since 2019" */
  basis: string;
  asserted_at_ms: bigint;
}

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * Broadcast — PRIORITY_BROADCAST, <= 512 bytes total (SIG-26)
 * ─────────────────────────────────────────────────────────────────────────────
 */
export interface BroadcastEmit {
  channel: string;
  /** Monotonic per channel — see BC-01 below. */
  sequence: bigint;
  severity: Severity;
  category: BroadcastCategory;
  /** <= 120 chars — must fit one LoRa frame, actionable alone. */
  headline: string;
  /** Omitted when the transport MTU cannot carry it (BC-04). */
  detail: string;
  area?: GeoArea | undefined;
  expires_at_ms: bigint;
  /** content_id of a broadcast this corrects. */
  supersedes: string;
  language: string;
}

/**
 * BC-02: a false alarm in a crisis is dangerous, so retraction is first-class.
 * BC-03: a revoked broadcast is marked revoked, NOT deleted — subscribers who acted
 * on it need to see that it was retracted and why.
 */
export interface BroadcastRevoke {
  channel: string;
  /** content_id being retracted. */
  target: string;
  reason: RevokeReason;
  note: string;
}

/**
 * Fixed-point degrees x 1e5. Integers only — EN-01 forbids floats in signed structures.
 * CR-02: coarse by default; precise coordinates require explicit per-message opt-in.
 */
export interface GeoArea {
  lat_e5: number;
  lon_e5: number;
  radius_m: number;
  place_name: string;
}

/**
 * MS-04: publishable ahead of time so a sender can start a session while the recipient
 * is offline. Without this, store-and-forward messaging cannot work.
 */
export interface PrekeyBundle {
  /** Ed25519 */
  identity_key: Uint8Array;
  /** X25519 */
  signed_prekey: Uint8Array;
  signed_prekey_sig: Uint8Array;
  /** ML-KEM-768 */
  kem_public_key: Uint8Array;
  one_time_prekeys: Uint8Array[];
  valid_until_ms: bigint;
}

export interface SignalSessionInit {
  recipient_key: Uint8Array;
  /** ML-KEM-768 encapsulation. */
  kem_ciphertext: Uint8Array;
  ephemeral_x25519: Uint8Array;
  used_prekey_id: Uint8Array;
  /** First message, ChaCha20-Poly1305. */
  ciphertext: Uint8Array;
}

export interface SignalMessage {
  /** content_id of the SessionInit. */
  session: string;
  /** Ratchet counter — gap and reorder detection (MS-05). */
  counter: bigint;
  /** Encrypted ratchet header. */
  header: Uint8Array;
  ciphertext: Uint8Array;
  /** content_ids, separately encrypted (MSG-24). */
  attachment_refs: string[];
}

export interface SignalDeliveryReceipt {
  message: string;
  state: DeliveryState;
}

/** MS-06: sender-keys model, capped at 64 members. Larger coordination uses a channel. */
export interface SignalGroupCreate {
  name: string;
  member_keys: Uint8Array[];
  group_key_wrapped: Uint8Array;
}

export interface SignalGroupUpdate {
  group: string;
  add: Uint8Array[];
  remove: Uint8Array[];
  /** MSG-25 — rekey on every membership change. */
  rekey_wrapped: Uint8Array;
}

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * Crisis reporting
 *
 * CR-01 / CRS-03: CheckIn costs ZERO credits and requires no credential. In a disaster,
 * telling people you are alive must never be rate-limited. This is the one action in
 * the system with no cost gate at all, and it is deliberate.
 * ─────────────────────────────────────────────────────────────────────────────
 */
export interface CheckIn {
  status: CheckInStatus;
  /** Optional, coarse by default. */
  area?:
    | GeoArea
    | undefined;
  /** <= 80 chars. */
  note: string;
  /** Trusted contacts. */
  notify_keys: Uint8Array[];
}

export interface MissingPersonReport {
  name: string;
  age: number;
  description: string;
  last_seen_place: string;
  last_seen_at_ms: bigint;
  contact_channel: string;
  photos: string[];
  status: MissingStatus;
}

export interface ResourceReport {
  kind: ResourceKind;
  area?: GeoArea | undefined;
  detail: string;
  state: ResourceState;
  observed_at_ms: bigint;
}

/**
 * SB-01: LOCAL ONLY. This message MUST NOT be serialised into an envelope or
 * transmitted. It is defined here so the client has a stable persisted shape, and its
 * absence from registry.yaml is what enforces that it can never be sent.
 */
export interface LocalSubscription {
  channel: string;
  alert_critical: boolean;
  alert_warning: boolean;
  alert_advisory: boolean;
  alert_info: boolean;
  area_filter?: GeoArea | undefined;
  category_filter: BroadcastCategory[];
  muted_until_ms: bigint;
}

/**
 * SB-02: opt-in, server-visible, ONLY for push delivery. The UI must state plainly
 * that enabling this reveals the subscription to the server, before the user enables it.
 */
export interface ChannelSubscribe {
  channel: string;
  push: boolean;
  push_token: Uint8Array;
}

